export const KIND = {"id":56,"example":{"id":"E56","kind":56,"source":"aether","statement":["Write a function `text_kind::describe(const std::string& text)` that returns one of four answers for the text.","When it holds a digit and a letter: `mixed`.","When it holds a digit and no letter: `digits`.","When it holds a letter and no digit: `letters`.","Else: `none`.","Limits: 0 ≤ length of text ≤ 1000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <cctype>","#include <string>","","namespace text_kind {","","std::string describe(const std::string& text)","{","    bool digit {false};","    bool letter {false};","    for (const char character : text) {","        if (std::isalpha(character)) {","            letter = true;","        } else if (std::isdigit(character)) {","            digit = true;","        }","    }","    if (digit && letter) {","        return \"mixed\";","    } else if (digit) {","        return \"digits\";","    } else if (letter) {","        return \"letters\";","    } else {","        return \"none\";","    }","}","","}  // namespace text_kind"],"frame":[0,2,3,5,29],"labels":[{"at":7,"level":1,"text":"Write a function that keeps what it finds in each character of the text, then gives back the answer for it."},{"at":9,"level":2,"text":"Start with no digit and no letter found."},{"at":9,"level":0,"text":"Make a `bool` variable, which holds `true` or `false`, and start it at `false`."},{"at":11,"level":2,"text":"Keep whether a digit or a letter comes."},{"at":12,"level":0,"text":"Test whether a character is a letter with `std::isalpha`."},{"at":18,"level":2,"text":"Test each case in order, and give back the answer of the first that holds."}],"blanks":[]}},"trace":{"id":"T56","lines":["#include <iostream>","#include <print>","#include <string>","","bool asks(const std::string& line)","{","    char last {' '};","    for (const char character : line) {","        last = character;","    }","    return last == '?';","}","int main()","{","    std::string line {};","    std::getline(std::cin, line);","    std::println(\"{}\", asks(line));","}"],"columns":["line","character","last"],"inputs":["ok?\n","why\n"],"rows":[{"line":15,"values":["","",""]},{"line":16,"values":["ok?","",""]},{"line":7,"values":["ok?",""," "]},{"line":8,"values":["ok?","o"," "]},{"line":9,"values":["ok?","o","o"]},{"line":8,"values":["ok?","k","o"]},{"line":9,"values":["ok?","k","k"]},{"line":8,"values":["ok?","?","k"]},{"line":9,"values":["ok?","?","?"]},{"line":8,"values":["ok?","","?"]},{"line":11,"values":["ok?","","?"]},{"line":17,"values":["ok?","",""]}],"output":"false\n"},"traces":[],"problems":{"56.01":{"id":"56.01","kind":56,"source":"exercism","statement":["Write a function `bob::hey(const std::string& text)` that returns one of five answers for the text.","When the text is empty or holds only spaces, tabs, line ends and returns: `Fine. Be that way!`.","When the text has a capital letter and no small letter, and its last character that is not white space is `?`: `Calm down, I know what I'm doing!`.","When the text has a capital letter and no small letter otherwise: `Whoa, chill out!`.","When the last character that is not white space is `?` otherwise: `Sure.`.","Else: `Whatever.`.","Limits: 0 ≤ length of text ≤ 1000; text holds printable ASCII characters and white space."],"examples":[{"input":"stating_something","output":""}],"tests":[{"input":"shouting","output":""},{"input":"shouting_gibberish","output":""},{"input":"asking_a_question","output":""},{"input":"asking_a_numeric_question","output":""},{"input":"asking_gibberish","output":""},{"input":"talking_forcefully","output":""},{"input":"using_acronyms_in_regular_speech","output":""},{"input":"forceful_questions","output":""},{"input":"shouting_numbers","output":""},{"input":"no_letters","output":""},{"input":"question_with_no_letters","output":""},{"input":"shouting_with_special_characters","output":""},{"input":"shouting_with_no_exclamation_mark","output":""},{"input":"statement_containing_question_mark","output":""},{"input":"non_letters_with_question","output":""},{"input":"prattling_on","output":""},{"input":"silence","output":""},{"input":"prolonged_silence","output":""},{"input":"alternate_silence","output":""},{"input":"multiple_line_question","output":""},{"input":"starting_with_whitespace","output":""},{"input":"ending_with_whitespace","output":""},{"input":"other_whitespace","output":""},{"input":"non_question_ending_with_whitespace","output":""},{"input":"shouting_a_statement_containing_a_question_mark","output":""}],"solution":{"lines":["#pragma once","","#include <cctype>","#include <string>","","namespace bob {","","std::string hey(const std::string& text)","{","    bool capital {false};","    bool small {false};","    char last {' '};","    for (const char character : text) {","        if (std::isupper(character)) {","            capital = true;","        } else if (std::islower(character)) {","            small = true;","        }","        if (!std::isspace(character)) {","            last = character;","        }","    }","    if (last == ' ') {","        return \"Fine. Be that way!\";","    } else if (capital && !small && last == '?') {","        return \"Calm down, I know what I'm doing!\";","    } else if (capital && !small) {","        return \"Whoa, chill out!\";","    } else if (last == '?') {","        return \"Sure.\";","    } else {","        return \"Whatever.\";","    }","}","","}  // namespace bob"],"frame":[0,2,3,5,35],"labels":[{"at":7,"level":1,"text":"Write a function that keeps what it finds in each character of the text, then gives back the answer for it."},{"at":9,"level":2,"text":"Start with no letter found and a space as the last character."},{"at":12,"level":2,"text":"Keep whether a capital or small letter comes, and the last character that is not white space."},{"at":22,"level":2,"text":"Test each case in order, and give back the answer of the first that holds."}],"blanks":[{"line":7,"from":16,"to":39},{"line":11,"from":15,"to":18},{"line":18,"from":12,"to":36},{"line":22,"from":8,"to":19}]},"fn":{"slug":"bob","commit":"8d139cb0","header":"bob.h","name":"bob_test.cpp","test":"#include \"bob.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\n// Bob exercise test case data version 1.4.0\n\nTEST_CASE(\"stating_something\", \"[e162fead-606f-437a-a166-d051915cea8e]\") {\n    REQUIRE(\"Whatever.\" == bob::hey(\"Tom-ay-to, tom-aaaah-to.\"));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"shouting\", \"[73a966dc-8017-47d6-bb32-cf07d1a5fcd9]\") {\n    REQUIRE(\"Whoa, chill out!\" == bob::hey(\"WATCH OUT!\"));\n}\n\nTEST_CASE(\"shouting_gibberish\", \"[d6c98afd-df35-4806-b55e-2c457c3ab748]\") {\n    REQUIRE(\"Whoa, chill out!\" == bob::hey(\"FCECDFCAAB\"));\n}\n\nTEST_CASE(\"asking_a_question\", \"[8a2e771d-d6f1-4e3f-b6c6-b41495556e37]\") {\n    REQUIRE(\"Sure.\" ==\n            bob::hey(\"Does this cryogenic chamber make me look fat?\"));\n}\n\nTEST_CASE(\"asking_a_numeric_question\",\n          \"[81080c62-4e4d-4066-b30a-48d8d76920d9]\") {\n    REQUIRE(\"Sure.\" == bob::hey(\"You are, what, like 15?\"));\n}\n\nTEST_CASE(\"asking_gibberish\", \"[2a02716d-685b-4e2e-a804-2adaf281c01e]\") {\n    REQUIRE(\"Sure.\" == bob::hey(\"fffbbcbeab?\"));\n}\n\nTEST_CASE(\"talking_forcefully\", \"[c02f9179-ab16-4aa7-a8dc-940145c385f7]\") {\n    REQUIRE(\"Whatever.\" == bob::hey(\"Let's go make out behind the gym!\"));\n}\n\nTEST_CASE(\"using_acronyms_in_regular_speech\",\n          \"[153c0e25-9bb5-4ec5-966e-598463658bcd]\") {\n    REQUIRE(\"Whatever.\" ==\n            bob::hey(\"It's OK if you don't want to go to the DMV.\"));\n}\n\nTEST_CASE(\"forceful_questions\", \"[a5193c61-4a92-4f68-93e2-f554eb385ec6]\") {\n    REQUIRE(\"Calm down, I know what I'm doing!\" ==\n            bob::hey(\"WHAT THE HELL WERE YOU THINKING?\"));\n}\n\nTEST_CASE(\"shouting_numbers\", \"[a20e0c54-2224-4dde-8b10-bd2cdd4f61bc]\") {\n    REQUIRE(\"Whoa, chill out!\" == bob::hey(\"1, 2, 3 GO!\"));\n}\n\nTEST_CASE(\"no_letters\", \"[f7bc4b92-bdff-421e-a238-ae97f230ccac]\") {\n    REQUIRE(\"Whatever.\" == bob::hey(\"1, 2, 3\"));\n}\n\nTEST_CASE(\"question_with_no_letters\",\n          \"[bb0011c5-cd52-4a5b-8bfb-a87b6283b0e2]\") {\n    REQUIRE(\"Sure.\" == bob::hey(\"4?\"));\n}\n\nTEST_CASE(\"shouting_with_special_characters\",\n          \"[496143c8-1c31-4c01-8a08-88427af85c66]\") {\n    REQUIRE(\"Whoa, chill out!\" ==\n            bob::hey(\"ZOMG THE %^*@#$(*^ ZOMBIES ARE COMING!!11!!1!\"));\n}\n\nTEST_CASE(\"shouting_with_no_exclamation_mark\",\n          \"[e6793c1c-43bd-4b8d-bc11-499aea73925f]\") {\n    REQUIRE(\"Whoa, chill out!\" == bob::hey(\"I HATE THE DMV\"));\n}\n\nTEST_CASE(\"statement_containing_question_mark\",\n          \"[aa8097cc-c548-4951-8856-14a404dd236a]\") {\n    REQUIRE(\"Whatever.\" == bob::hey(\"Ending with ? means a question.\"));\n}\n\nTEST_CASE(\"non_letters_with_question\",\n          \"[9bfc677d-ea3a-45f2-be44-35bc8fa3753e]\") {\n    REQUIRE(\"Sure.\" == bob::hey(\":) ?\"));\n}\n\nTEST_CASE(\"prattling_on\", \"[8608c508-f7de-4b17-985b-811878b3cf45]\") {\n    REQUIRE(\"Sure.\" == bob::hey(\"Wait! Hang on. Are you going to be OK?\"));\n}\n\nTEST_CASE(\"silence\", \"[bc39f7c6-f543-41be-9a43-fd1c2f753fc0]\") {\n    REQUIRE(\"Fine. Be that way!\" == bob::hey(\"\"));\n}\n\nTEST_CASE(\"prolonged_silence\", \"[d6c47565-372b-4b09-b1dd-c40552b8378b]\") {\n    REQUIRE(\"Fine. Be that way!\" == bob::hey(\"          \"));\n}\n\nTEST_CASE(\"alternate_silence\", \"[4428f28d-4100-4d85-a902-e5a78cb0ecd3]\") {\n    REQUIRE(\"Fine. Be that way!\" == bob::hey(\"\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\"));\n}\n\nTEST_CASE(\"multiple_line_question\", \"[2c7278ac-f955-4eb4-bf8f-e33eb4116a15]\") {\n    REQUIRE(\"Sure.\" ==\n            bob::hey(\"\\nDoes this cryogenic chamber make\\n me look fat?\"));\n}\n\nTEST_CASE(\"starting_with_whitespace\",\n          \"[5371ef75-d9ea-4103-bcfa-2da973ddec1b]\") {\n    REQUIRE(\"Whatever.\" == bob::hey(\"         hmmmmmmm...\"));\n}\n\nTEST_CASE(\"ending_with_whitespace\", \"[05b304d6-f83b-46e7-81e0-4cd3ca647900]\") {\n    REQUIRE(\"Sure.\" == bob::hey(\"Okay if like my  spacebar  quite a bit?   \"));\n}\n\nTEST_CASE(\"other_whitespace\", \"[72bd5ad3-9b2f-4931-a988-dce1f5771de2]\") {\n    REQUIRE(\"Fine. Be that way!\" == bob::hey(\"\\n\\r \\t\"));\n}\n\nTEST_CASE(\"non_question_ending_with_whitespace\",\n          \"[12983553-8601-46a8-92fa-fcaa3bc4a2a0]\") {\n    REQUIRE(\"Whatever.\" ==\n            bob::hey(\"This is a statement ending with whitespace      \"));\n}\nTEST_CASE(\"shouting_a_statement_containing_a_question_mark\",\n          \"[3c954328-86fb-4c71-8961-e18d6a5e2517]\") {\n    REQUIRE(\"Whoa, chill out!\" == bob::hey(\"DO LIONS EAT PEOPLE? AHHHHH.\"));\n}\n#endif\n","setup":[],"calls":[{"call":"bob::hey(\"Tom-ay-to, tom-aaaah-to.\")","expected":"\"Whatever.\""}]}},"56.02":{"id":"56.02","kind":56,"source":"aether","statement":["Write a function `strength::rate(const std::string& text)` that returns one of three answers for the text.","When it holds at least 8 characters, a digit, a capital letter and a small letter: `strong`.","When it holds at least 2 of these 3: a digit, a capital letter, a small letter: `medium`.","Else: `weak`.","Limits: 0 ≤ length of text ≤ 1000; text holds printable ASCII characters."],"examples":[{"input":"strong","output":""}],"tests":[{"input":"empty","output":""},{"input":"one_character","output":""},{"input":"only_small","output":""},{"input":"only_digits","output":""},{"input":"only_signs","output":""},{"input":"all_three_but_short","output":""},{"input":"seven_characters","output":""},{"input":"eight_characters","output":""},{"input":"digit_and_capital","output":""},{"input":"capital_and_small","output":""},{"input":"digit_and_small","output":""},{"input":"largest","output":""}],"solution":{"lines":["#pragma once","","#include <cctype>","#include <string>","","namespace strength {","","std::string rate(const std::string& text)","{","    bool digit {false};","    bool capital {false};","    bool small {false};","    for (const char character : text) {","        if (std::isdigit(character)) {","            digit = true;","        } else if (std::isupper(character)) {","            capital = true;","        } else if (std::islower(character)) {","            small = true;","        }","    }","    if (text.size() >= 8 && digit && capital && small) {","        return \"strong\";","    } else if (digit + capital + small >= 2) {","        return \"medium\";","    } else {","        return \"weak\";","    }","}","","}  // namespace strength"],"frame":[0,2,3,5,30],"labels":[{"at":7,"level":1,"text":"Write a function that keeps what it finds in each character of the text, then gives back the answer for it."},{"at":9,"level":2,"text":"Start with no digit, capital or small letter found."},{"at":12,"level":2,"text":"Keep whether a digit, a capital or a small letter comes."},{"at":21,"level":2,"text":"Test each case in order, and give back the answer of the first that holds."}],"blanks":[{"line":7,"from":17,"to":40},{"line":11,"from":16,"to":21},{"line":17,"from":19,"to":42},{"line":21,"from":8,"to":53}]},"fn":{"slug":"strength","commit":"","header":"strength.h","name":"strength_test.cpp","test":"#include \"strength.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"strong\") { REQUIRE(strength::rate(\"Secret123\") == \"strong\"); }\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"empty\") { REQUIRE(strength::rate(\"\") == \"weak\"); }\nTEST_CASE(\"one_character\") { REQUIRE(strength::rate(\"a\") == \"weak\"); }\nTEST_CASE(\"only_small\") {\n    REQUIRE(strength::rate(\"abcdefghij\") == \"weak\");\n}\nTEST_CASE(\"only_digits\") { REQUIRE(strength::rate(\"12345678\") == \"weak\"); }\nTEST_CASE(\"only_signs\") { REQUIRE(strength::rate(\"!@# $%^&*\") == \"weak\"); }\nTEST_CASE(\"all_three_but_short\") {\n    REQUIRE(strength::rate(\"aB3\") == \"medium\");\n}\nTEST_CASE(\"seven_characters\") {\n    REQUIRE(strength::rate(\"aB3defg\") == \"medium\");\n}\nTEST_CASE(\"eight_characters\") {\n    REQUIRE(strength::rate(\"aB3defgh\") == \"strong\");\n}\nTEST_CASE(\"digit_and_capital\") {\n    REQUIRE(strength::rate(\"ABC12345\") == \"medium\");\n}\nTEST_CASE(\"capital_and_small\") {\n    REQUIRE(strength::rate(\"Password\") == \"medium\");\n}\nTEST_CASE(\"digit_and_small\") {\n    REQUIRE(strength::rate(\"pass word 1\") == \"medium\");\n}\nTEST_CASE(\"largest\") {\n    std::string text(997, '-');\n    text += \"x7Y\";\n    REQUIRE(strength::rate(text) == \"strong\");\n}\n#endif\n","setup":[],"calls":[{"call":"strength::rate(\"Secret123\")","expected":"\"strong\""}]}}}}
